package za.co.goodstuffcatering.data.remote.dto

/**
 * DTO received when an order is successfully created.
 */
data class OrderResponse(
    // A unique string identifier for the order generated by Django
    val orderId: String,
    // Status (e.g., "Pending")
    val status: String,
    // The confirmed total amount
    val totalAmount: Double
)
